	@Test
	void secureModeRejectsUnlistedRedirectBeforeRequest() throws Exception {
		for (boolean cache : new boolean[] { false, true }) {
			AtomicInteger forbiddenRequests = new AtomicInteger();
			HttpServer server = newServer();
			try {
				server.createContext("/allowed", exchange -> {
					exchange.getResponseHeaders().set("Location", "/forbidden");
					exchange.sendResponseHeaders(302, -1);
					exchange.close();
				});
				server.createContext("/forbidden", exchange -> {
					forbiddenRequests.incrementAndGet();
					respond(exchange, "application/ld+json", CONTEXT);
				});
				server.start();

				URI allowed = URI.create("http://127.0.0.1:" + server.getAddress().getPort() + "/allowed");
				CachingDocumentLoader loader = new CachingDocumentLoader(true, Set.of(allowed.toString()), cache);
				assertThrows(RDFParseException.class,
						() -> loader.loadDocument(allowed, new DocumentLoaderOptions()));
				assertEquals(0, forbiddenRequests.get());
			} finally {
				server.stop(0);
			}
		}
	}

