	@Test
	void cacheDoesNotTransferDocumentAcrossSecurityPolicies() throws Exception {
		HttpServer server = newServer();
		try {
			server.createContext("/allowed", exchange -> {
				exchange.getResponseHeaders().set("Location", "/forbidden");
				exchange.sendResponseHeaders(302, -1);
				exchange.close();
			});
			server.createContext("/forbidden", exchange -> respond(exchange, "application/ld+json", CONTEXT));
			server.start();

			URI allowed = URI.create("http://127.0.0.1:" + server.getAddress().getPort() + "/allowed");
			DocumentLoaderOptions options = new DocumentLoaderOptions();
			assertTrue(new CachingDocumentLoader(false, Set.of(), true)
					.loadDocument(allowed, options)
					.getJsonContent()
					.isPresent());
			assertTrue(new CachingDocumentLoader(true,
					Set.of(allowed.toString(), allowed.resolve("/forbidden").toString()), true)
							.loadDocument(allowed, options)
							.getJsonContent()
							.isPresent());
			assertThrows(RDFParseException.class, () -> new CachingDocumentLoader(true,
					Set.of(allowed.toString()), true).loadDocument(allowed, options));
		} finally {
			server.stop(0);
		}
	}

	@Test
	void cachePreservesRequestProfileOptions() throws Exception {
		AtomicInteger requests = new AtomicInteger();
		HttpServer server = newServer();
		try {
			server.createContext("/context", exchange -> {
				requests.incrementAndGet();
				String accept = exchange.getRequestHeaders().getFirst("Accept");
				String term = accept.contains("profile-b") ? "https://example.org/b" : "https://example.org/a";
				respond(exchange, "application/ld+json", "{\"@context\":{\"term\":\"" + term + "\"}}");
			});
			server.start();

			URI uri = URI.create("http://127.0.0.1:" + server.getAddress().getPort() + "/context");
			CachingDocumentLoader loader = new CachingDocumentLoader(true, Set.of(uri.toString()), true);
			DocumentLoaderOptions first = new DocumentLoaderOptions();
			first.setRequestProfile(List.of("https://example.org/profile-a"));
			DocumentLoaderOptions second = new DocumentLoaderOptions();
			second.setRequestProfile(List.of("https://example.org/profile-b"));
			assertTrue(loader.loadDocument(uri, first).getJsonContent().orElseThrow().toString().contains("/a"));
			assertTrue(loader.loadDocument(uri, second).getJsonContent().orElseThrow().toString().contains("/b"));
			assertTrue(loader.loadDocument(uri, first).getJsonContent().orElseThrow().toString().contains("/a"));
			assertEquals(2, requests.get());
		} finally {
			server.stop(0);
		}
	}

